def protocol_handlers(cls, protocol_version=None):
    '''Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
    If an explicit protocol version is provided, the dictionary will contain
    either zero or one items, depending on whether that version is supported.
    If no protocol version is provided, all available versions will be returned.
    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5))
    or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    '''

    protocol_versions = {}
    for version in cls.AVAILABLE_PROTOCOL_VERSIONS:
        if version[0] == protocol_version[0] and version[1] == protocol_version[1]:
            protocol_versions[version] = cls.PROTOCOL_VERSIONS[version[0]][version[1]]
    if protocol_version is not None:
        if not len(protocol_versions) == 1:
            raise TypeError(f'Expected a single version tuple of the form (major, minor), '
                            f'but got {protocol_version}')
    return protocol_versions

