def _inline_r_setup(code: str) -> str:
    import subprocess
    from pathlib import Path

    R_OPTIONS = "_R_OPTIONS"
    R_OPTIONS_FILE = "_R_OPTIONS_FILE"

    def _get_r_options_path(filename: str) -> str:
        """Gets the path to the R options file for a given script."""
        return str(Path(filename).absolute()).replace(".R", ".options")

    def _load_r_options(filename: str) -> str:
        """Loads the R options from a file."""
        return subprocess.run(["Rscript", "--load", R_OPTIONS_FILE], capture_output=True, input=code.encode("utf-8")).stdout.decode("utf-8")

    def _write_r_options(filename: str) -> str:
        """Writes the R options to a file."""
        return subprocess.run(["Rscript", "--save", R_OPTIONS_FILE], capture_output=True, input=code.encode("utf-8")).stdout.decode("utf-8")

    filename = code.split(" ")[1]
    if filename.endswith(".R"):
        r_options_path = _get_r_options_path(filename)
        if Path(r_options_path).exists():
            r_options = _load_r_options(r_options_path)
        else:
            r_options = _write_r_options(r_options_path)
        return f"{R_OPTIONS}={{{r_options}}}"
    else:
        return ""

