        @functools.wraps(func)
        def wrapper(*args):
            key = _gen_key(func, args, typed)
            if key in cache:
                (value, created, _) = cache[key]
                if timer() - created > ttl:
                    cache.pop(key)
                    return func(*args)
                else:
                    return value
            else:
                value = func(*args)
                cache[key] = (value, timer(), maxsize)
                return value
        return wrapper
    return decorator

