def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    if os.path.isfile(file_name):
        if not overwrite:
            # Open file in append mode and write the text_buffer
            with open(file_name, "a", encoding=encoding) as f:
                f.write(text_buffer)
        else:
            # Open file in write mode and write the text_buffer
            with open(file_name, "w", encoding=encoding) as f:
                f.write(text_buffer)
    else:
        # Create file and write the text_buffer
        with open(file_name, "w", encoding=encoding) as f:
            f.write(text_buffer)
    return len(text_buffer)

