def fill(self, coord, weight=1):
    if not ((coord >= self.edges[0][0]) and (coord <= self.edges[0][-1])):
        return

    bin_idx = np.searchsorted(self.edges[0], coord)
    self.values[0][bin_idx] += weight
    self.values[1][bin_idx] += weight**2

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if coord not in self.edges:
        return

    if coord not in self.centers:
        self.centers.append(coord)

    self.bins[coord] += weight

    if self.bins[coord] > self.edges[coord]:
        self.too_high.append(coord)

    if self.bins[coord] < 0:
        self.too_low.append(coord)

    self.update()

