def validate(path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.

    :param path: The path to the OCFL object.
    :type path: str
    :return: True if the object is valid, False otherwise.
    :rtype: bool
    """

    # Check if the path exists and is a directory
    if not os.path.exists(path):
        raise ValueError(f"Path {path} does not exist")
    if not os.path.isdir(path):
        raise ValueError(f"Path {path} is not a directory")

    # Check if the object root directory contains the required files (base.json and metadata.nt)
    for file in ("base.json", "metadata.nt"):
        if not os.path.exists(os.path.join(path, file)):
            raise ValueError(f"Object root directory {path} is missing file {file}")

