def validate_as_prior_version(self, prior):
        if self.version == prior.version:
            raise ValueError("Both inventory and prior have the same version: %i" % self.version)
        if self.version != prior.version + 1:
            raise ValueError("Inventory version %i is not a valid prior version for version %i" % (self.version, prior.version))
