def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for did in inventory:
        logical_path = did.version_path + "/" + did.file_name
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(did)

    return logical_path_map

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for state in inventory:
        if state.version == version:
            for file in state.files:
                logical_path = file.logical_path_in_state
                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = []
                logical_path_map[logical_path].append(file)
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        logical_path_key = (item["logical_path_in_state"] + item["version"]).strip()
        if logical_path_key not in logical_path_map:
            logical_path_map[logical_path_key] = set()
        logical_path_map[logical_path_key].add(item["content_file"])
    return logical_path_map

