    for key, value in fixity.items():
        if key in required_keys:
            if not value:
                raise ValueError("Fixity block has an empty value for required key: {}".format(key))
            if key == "@type" and value not in ["md5", "sha1", "sha256"]:
                raise ValueError("Fixity block has an invalid value for key: {}".format(key))
            if key == "algorithm" and value not in ["http://www.w3.org/ns/ checksus -type#md5", "http://www.w3.org/ns/checksum -type#sha1", "http://www.w3.org/ns/checksum -type#sha256"]:
                raise ValueError("Fixity block has an invalid value for key: {}".format(key))
            if key == "digest" and len(value) < 32:
                raise ValueError("Fixity block has an invalid value for key: {}".format(key))

