def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size_suffix = size[-1].upper()
    try:
        size_num = float(size[:-1])
    except ValueError:
        raise ValueError("Invalid size string")

    if size_suffix == "K":
        return size_num * 1024
    elif size_suffix == "M":
        return size_num * 1024 * 1024
    elif size_suffix == "G":
        return size_num * 1024 * 1024 * 1024
    else:
        return size_num

def size_to_bytes(size):
    units = {'B': 1, 'KB': 1000, 'MB': 1000 * 1000, 'GB': 1000 * 1000 * 1000, 'TB': 1000 * 1000 * 1000 * 1000}
    size = size.upper()
    if size[-1] not in units:
        return -1
    return int(size[:-1]) * units[size[-1]]

