def scale(self, other=None, recompute=False):
    if other is None and not recompute:
        if self.scale is None:
            self.summarize()
        return self.scale

    if recompute:
        self.summarize()
        return self.scale

    if isinstance(other, Histogram):
        if self.dimensions != other.dimensions:
            raise ValueError("Histograms have different dimensions")
        if self.axis_names != other.axis_names:
            raise ValueError("Histograms have different axis names")
        if self.axis_ranges != other.axis_ranges:
            raise ValueError("Histograms have different axis ranges")
    elif isinstance(other, (int, float)):
        self.histogram *= other
    else:
        raise TypeError("Type of other must be Histogram or int/float")
    self.summarize()
    return self.scale

def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, "_scale") or recompute:
            self._scale = np.sum(self.histogram)
        return self._scale
    elif isinstance(other, float):
        if self._scale == 0:
            raise LenaValueError("Histogram with scale equal to zero can't be rescaled")
        self.histogram *= other / self._scale
        self._scale = other
    else:
        raise LenaValueError("Other must be None or a float")

