def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    # Making sure the candidate claims that it provides the interface
    if not (tentative or iface.providedBy(candidate)):
        raise zope.interface.Invalid("Candidate does not provide the interface")

    # Making sure the candidate defines all the necessary methods
    for name, spec in iface.namesAndDescriptions():
        if spec.isMethod():
            if hasattr(candidate, name):
                method = getattr(candidate, name)
                if method is None:
                    raise zope.interface.Invalid("Candidate defines a method %s that is None" % name)
                elif not callable(method):
                    raise zope.interface.Invalid("Candidate defines a method %s that is not callable" % name)
            else:
                raise zope.interface.Invalid("Candidate does not define a method %s" % name)

    # Making sure the methods have the correct signature (to the
    # extent possible)
    for name, spec in iface.namesAndDescriptions():
        if spec.isMethod():
            method = getattr(candidate, name)
            try:
                args, varargs, keywords, defaults = inspect.getargspec(method)
            except TypeError:
                # method with no inspectable arg spec
                pass
            else:
                # Compare positional argument specs
                spec_args = spec.getPositionalArgs()
                if varargs is not None or spec_args:
                    if not spec_args or spec_args[0] != "self":
                        # missing self or specified positional args without implicit self
                        raise zope.interface.Invalid("Method %s does not specify implicit self "
                                                      "or named args in its signature" % name)
                    elif spec_args[0] != "self" or args != spec_args[0]:
                        # optional args or arg spec that does not match
                        raise zope.interface.Invalid("Method %s does not match its signature" % name)

    # Making sure the candidate defines all the necessary attributes
    for name, spec in iface.namesAndDescriptions():
        if spec.isAttribute():
            if hasattr(candidate, name):
                attribute = getattr(candidate, name)
                if not isinstance(attribute, spec.getObjectType()):
                    raise zope.interface.Invalid(
                        "Candidate defines an attribute %s with the wrong type" % name)
            else:
                raise zope.interface.Invalid("Candidate does not define an attribute %s" % name)

    return True

