def fetch_content_type(url: str) -> Optional[str]:
    try:
        req = urllib.request.Request(url)
        req.get_method = lambda: 'HEAD'
        resp = urllib.request.urlopen(req)
        content_type = resp.headers['content-type']
        resp.close()
    except urllib.error.URLError as e:
        return None
    except KeyError as e:
        return None
    else:
        return content_type

def fetch_content_type(url):
        """Fetch the HEAD of the remote url to determine the content type."""
        req = urllib2.Request(url, headers={'Host': urlparse.urlsplit(url).netloc})
        resp = urllib2.urlopen(req)
        try:
            if hasattr(resp, 'code') and resp.code != 200:
                return None
            return resp.info().get('content-type', None)
        finally:
            resp.close()

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = urllib.request.Request(url, headers={'Host': netloc}, method='HEAD')
    resp = urllib.request.urlopen(req)
    try:
        if hasattr(resp, 'error') and resp.error:
            return None
        return resp.info().get('content-type', None)
    finally:
        resp.close()

