def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """

    if not isinstance(dic, dict):
        raise TypeError("dic parameter must be of type dict")
    if not isinstance(val, (int, float, str, bool, list, dict)):
        raise TypeError("val parameter must be of type int, float, str, bool, list, or dict")
    if not isinstance(key, str):
        raise TypeError("key parameter must be of type str")
    if keys is not None and not all(isinstance(item, str) for item in keys):
        raise TypeError("keys parameter must be a list of str")

    nested_dict = dic
    for k in [key] + keys:
        if k not in nested_dict:
            nested_dict[k] = {}
        nested_dict = nested_dict[k]

    nested_dict[key] = val

