def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    for plugin_name in os.listdir(plugin_dir):
        plugin_path = os.path.join(plugin_dir, plugin_name)
        if os.path.isdir(plugin_path):
            plugin_spec[plugin_name] = {}
            for plugin_setting in os.listdir(plugin_path):
                plugin_setting_path = os.path.join(plugin_path, plugin_setting)
                if os.path.isfile(plugin_setting_path):
                    with open(plugin_setting_path, "r") as f:
                        plugin_spec[plugin_name][plugin_setting] = f.read()
    return plugin_spec

